/**
 * Fix CP1252 smart-punctuation bytes that broke UTF-8 in posts.ts
 * (PowerShell Set-Content wrote 0x97 etc. into an otherwise UTF-8 file).
 */
import fs from "node:fs";

const path = "src/data/posts.ts";
const buf = fs.readFileSync(path);

const map = new Map([
  [0x80, Buffer.from([0xe2, 0x82, 0xac])], // ???
  [0x82, Buffer.from([0xe2, 0x80, 0x9a])], // ???
  [0x83, Buffer.from([0xc6, 0x92])], // ??
  [0x84, Buffer.from([0xe2, 0x80, 0xe2])], // will fix below
  [0x85, Buffer.from([0xe2, 0x80, 0xa6])], // ???
  [0x91, Buffer.from([0xe2, 0x80, 0x98])], // ???
  [0x92, Buffer.from([0xe2, 0x80, 0x99])], // ???
  [0x93, Buffer.from([0xe2, 0x80, 0x9c])], // ???
  [0x94, Buffer.from([0xe2, 0x80, 0x9d])], // ???
  [0x95, Buffer.from([0xe2, 0x80, 0xa2])], // ???
  [0x96, Buffer.from([0xe2, 0x80, 0x93])], // ???
  [0x97, Buffer.from([0xe2, 0x80, 0x94])], // ???
  [0x99, Buffer.from([0xe2, 0x84, 0xa2])], // ???
  [0xa0, Buffer.from([0xc2, 0xa0])], // nbsp
]);
// fix 0x84 double low-9 quotation
map.set(0x84, Buffer.from([0xe2, 0x80, 0x9e]));

function isUtf8Start(b) {
  return b <= 0x7f || (b >= 0xc2 && b <= 0xf4);
}

const out = [];
let i = 0;
let replaced = 0;
while (i < buf.length) {
  const b = buf[i];
  // Pass through valid ASCII
  if (b <= 0x7f) {
    out.push(b);
    i++;
    continue;
  }
  // Valid UTF-8 2-byte
  if (b >= 0xc2 && b <= 0xdf && i + 1 < buf.length && (buf[i + 1] & 0xc0) === 0x80) {
    out.push(b, buf[i + 1]);
    i += 2;
    continue;
  }
  // Valid UTF-8 3-byte
  if (b >= 0xe0 && b <= 0xef && i + 2 < buf.length && (buf[i + 1] & 0xc0) === 0x80 && (buf[i + 2] & 0xc0) === 0x80) {
    out.push(b, buf[i + 1], buf[i + 2]);
    i += 3;
    continue;
  }
  // Valid UTF-8 4-byte
  if (b >= 0xf0 && b <= 0xf4 && i + 3 < buf.length && (buf[i + 1] & 0xc0) === 0x80 && (buf[i + 2] & 0xc0) === 0x80 && (buf[i + 3] & 0xc0) === 0x80) {
    out.push(b, buf[i + 1], buf[i + 2], buf[i + 3]);
    i += 4;
    continue;
  }
  // Lone CP1252 byte
  if (map.has(b)) {
    const rep = map.get(b);
    for (const x of rep) out.push(x);
    replaced++;
    i++;
    continue;
  }
  // Fallback: replace with ?
  out.push(0x3f);
  replaced++;
  i++;
}

const fixed = Buffer.from(out);
// Validate
const text = fixed.toString("utf8");
if (text.includes("\uFFFD") && replaced === 0) {
  console.error("unexpected replacement chars");
  process.exit(1);
}
fs.writeFileSync(path, fixed);
console.log(`fixed ${path}: replaced=${replaced} newLen=${fixed.length}`);
// sanity: our post present
if (!text.includes("medical-collections-on-consumer-credit-reports-2026")) {
  console.error("post missing after fix");
  process.exit(1);
}
console.log("ok");

